import{_t as e,it as t,n,rt as r}from"./chunks/framework.CzJE1L4g.js";var i=JSON.parse(`{"title":"生态总览","description":"","frontmatter":{"title":"生态总览","index":false},"headers":[],"relativePath":"cosmos/ecosystem.md","filePath":"cosmos/ecosystem.md","lastUpdated":1792595762000}`),a={name:`cosmos/ecosystem.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="生态总览" tabindex="-1">生态总览 <a class="header-anchor" href="#生态总览" aria-label="Permalink to “生态总览”">​</a></h1><p>曦寒不是一个仓库，而是三个可以独立使用、也可以叠起来用的开源项目，外加打印、流程、表单、报表四款设计器。本页讲它们各自是什么、彼此什么关系、你的场景该从哪个进去。</p><p>它们各有独立的文档站，本站只负责生态层面的导览与共同的贡献约定。</p><h2 id="三个仓库" tabindex="-1">三个仓库 <a class="header-anchor" href="#三个仓库" aria-label="Permalink to “三个仓库”">​</a></h2><table tabindex="0"><thead><tr><th>定位</th><th>项目</th><th>技术栈</th><th>文档站</th></tr></thead><tbody><tr><td>后端基座</td><td><a href="https://github.com/XiHanFun/XiHan.Framework" target="_blank" rel="noreferrer">XiHan.Framework</a></td><td>.NET</td><td><a href="https://framework.docs.xihanfun.com/" target="_blank" rel="noreferrer">framework.docs.xihanfun.com</a></td></tr><tr><td>前端基座</td><td><a href="https://github.com/XiHanFun/XiHan.UI" target="_blank" rel="noreferrer">XiHan.UI</a></td><td>TypeScript · Vue · React · Web Components</td><td><a href="https://ui.docs.xihanfun.com/" target="_blank" rel="noreferrer">ui.docs.xihanfun.com</a></td></tr><tr><td>基础应用</td><td><a href="https://github.com/XiHanFun/XiHan.BasicApp" target="_blank" rel="noreferrer">XiHan.BasicApp</a></td><td>.NET + Vue</td><td><a href="https://basicapp.docs.xihanfun.com/" target="_blank" rel="noreferrer">basicapp.docs.xihanfun.com</a></td></tr></tbody></table><h3 id="xihan-framework-·-后端基座" tabindex="-1">XiHan.Framework · 后端基座 <a class="header-anchor" href="#xihan-framework-·-后端基座" aria-label="Permalink to “XiHan.Framework · 后端基座”">​</a></h3><p>快速、轻量、高效、用心的 .NET 现代模块化开发框架。是面向企业级应用的模块化后端框架，框架优先使用 .NET 原生功能，减少第三方依赖，理念现代、开箱即用、模块清晰、依赖可控、扩展可维护。曦寒懿（XiHanFun）开源生态的后端基座。</p><p>按需引用的 NuGet 包，模块之间用 <code>[DependsOn]</code> 声明依赖，启动时自动拓扑排序装配。</p><h3 id="xihan-ui-·-前端基座" tabindex="-1">XiHan.UI · 前端基座 <a class="header-anchor" href="#xihan-ui-·-前端基座" aria-label="Permalink to “XiHan.UI · 前端基座”">​</a></h3><p>快速、轻量、高效、用心的框架无关 Headless UI 组件库。是面向企业级前端的设计系统运行时，无头内核，多框架适配器。提供基础组件与 AI 组件，覆盖从中后台到 AI 对话的界面构建场景。曦寒懿（XiHanFun）开源生态的前端基座。</p><h3 id="xihan-basicapp-·-基础应用" tabindex="-1">XiHan.BasicApp · 基础应用 <a class="header-anchor" href="#xihan-basicapp-·-基础应用" aria-label="Permalink to “XiHan.BasicApp · 基础应用”">​</a></h3><p>基于 XiHan.Framework 和 XiHan.UI 的超高颜值通用中后台内核。开箱即用，提供 RBAC + 数据范围 + 字段脱敏的权限管理、多租户隔离、代码生成、实时通信、灰度发布、AI 等核心能力，满足新型企业级中后台管理场景。属于曦寒懿（XiHanFun）开源生态的基础应用。</p><h2 id="四款设计器" tabindex="-1">四款设计器 <a class="header-anchor" href="#四款设计器" aria-label="Permalink to “四款设计器”">​</a></h2><table tabindex="0"><thead><tr><th>设计器</th><th>项目</th><th>文档站</th></tr></thead><tbody><tr><td>打印设计器</td><td><a href="https://github.com/XiHanFun/XiHan.PrintDesigner" target="_blank" rel="noreferrer">XiHan.PrintDesigner</a></td><td><a href="https://print.docs.xihanfun.com/" target="_blank" rel="noreferrer">print.docs.xihanfun.com</a></td></tr><tr><td>流程设计器</td><td><a href="https://github.com/XiHanFun/XiHan.FlowDesigner" target="_blank" rel="noreferrer">XiHan.FlowDesigner</a></td><td><a href="https://flow.docs.xihanfun.com/" target="_blank" rel="noreferrer">flow.docs.xihanfun.com</a></td></tr><tr><td>表单设计器</td><td><a href="https://github.com/XiHanFun/XiHan.FormDesigner" target="_blank" rel="noreferrer">XiHan.FormDesigner</a></td><td><a href="https://form.docs.xihanfun.com/" target="_blank" rel="noreferrer">form.docs.xihanfun.com</a></td></tr><tr><td>报表设计器</td><td><a href="https://github.com/XiHanFun/XiHan.ReportDesigner" target="_blank" rel="noreferrer">XiHan.ReportDesigner</a></td><td><a href="https://report.docs.xihanfun.com/" target="_blank" rel="noreferrer">report.docs.xihanfun.com</a></td></tr></tbody></table><ul><li><strong>打印设计器</strong>：可视化设计打印模板，在浏览器里预览与打印；配合本地打印客户端可静默直打。</li><li><strong>流程设计器</strong>：可视化编排流程图与审批流，产出与流程引擎无关的流程定义，由使用方对接自己的引擎。</li><li><strong>表单设计器</strong>：可视化搭建表单，同一份 JSON 定义既驱动设计器，也驱动业务页面里的表单渲染。</li><li><strong>报表设计器</strong>：可视化设计数据报表与看板，数据由使用方通过回调提供。</li></ul><p>四款都是框架无关的设计器，以原生 Web Components 交付，Vue、React、Angular 或不使用框架的页面都能直接使用；运行时不引入任何第三方包。模板只是 JSON，不含也不执行任何代码；组件不发网络请求，数据、存储与权限都经回调交给使用方。</p><h2 id="彼此什么关系" tabindex="-1">彼此什么关系 <a class="header-anchor" href="#彼此什么关系" aria-label="Permalink to “彼此什么关系”">​</a></h2><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>      ┌───────────────────────────────┐</span></span>
<span class="line"><span>      │        XiHan.BasicApp         │  企业级中后台，可直接投产</span></span>
<span class="line"><span>      │  后端 modules/  ·  前端 src/  │</span></span>
<span class="line"><span>      └───────┬───────────────┬───────┘</span></span>
<span class="line"><span>              │ 引用 NuGet    │ 引用 npm 包</span></span>
<span class="line"><span>      ┌───────▼───────┐  ┌────▼─────────────┐</span></span>
<span class="line"><span>      │ XiHan.Framework│  │   XiHan.UI      │</span></span>
<span class="line"><span>      │  .NET 模块包   │  │  设计系统运行时  │</span></span>
<span class="line"><span>      └───────────────┘  └─────────────────┘</span></span></code></pre></div><p>两条依赖关系值得先说清楚：</p><ul><li><strong>BasicApp 的后端确实建立在 Framework 之上</strong>：它引用框架的 NuGet 包，认证、授权、数据访问、多租户、动态 API 等底层能力都来自框架，BasicApp 只写业务。想看框架能力在真实业务里怎么落地，读 BasicApp 的源码是最快的路径。</li><li><strong>BasicApp 的前端同样建立在 UI 之上</strong>：自 BasicApp v4.0.0 起，前端整体用 XiHan.UI 重建，naive-ui 全量下线。想看组件库在真实业务里怎么用，读 BasicApp 前端的源码是最快的路径。</li></ul><p>Framework 与 UI 之间没有依赖关系，一个是 .NET 后端包，一个是前端库，各自可以单独使用。</p><p>四款设计器建立在 UI 之上：运行时只依赖本产品与 XiHan.UI 的包，界面直接用 UI 的组件与设计器零件。</p><h2 id="我该从哪个进去" tabindex="-1">我该从哪个进去 <a class="header-anchor" href="#我该从哪个进去" aria-label="Permalink to “我该从哪个进去”">​</a></h2><table tabindex="0"><thead><tr><th>你的场景</th><th>从这里开始</th></tr></thead><tbody><tr><td>要在自己的 .NET 项目里用模块化框架、只取其中几个能力</td><td><a href="https://framework.docs.xihanfun.com/quickstart" target="_blank" rel="noreferrer">开发框架 · 快速上手</a></td></tr><tr><td>要一套现成的中后台系统，改改就能上线</td><td><a href="https://basicapp.docs.xihanfun.com/getting-started" target="_blank" rel="noreferrer">基础应用 · 快速开始</a></td></tr><tr><td>要在自己的前端项目里用组件库，或做跨框架的设计系统</td><td><a href="https://ui.docs.xihanfun.com/overview" target="_blank" rel="noreferrer">视图组件 · 架构总览</a></td></tr><tr><td>要在自己的页面里嵌打印、流程、表单或报表设计器</td><td><a href="https://print.docs.xihanfun.com/" target="_blank" rel="noreferrer">打印设计器</a> · <a href="https://flow.docs.xihanfun.com/" target="_blank" rel="noreferrer">流程设计器</a> · <a href="https://form.docs.xihanfun.com/" target="_blank" rel="noreferrer">表单设计器</a> · <a href="https://report.docs.xihanfun.com/" target="_blank" rel="noreferrer">报表设计器</a></td></tr><tr><td>还在选型，想先看清楚适合不适合</td><td><a href="https://framework.docs.xihanfun.com/why" target="_blank" rel="noreferrer">为什么选择曦寒框架</a> · <a href="https://basicapp.docs.xihanfun.com/why" target="_blank" rel="noreferrer">为什么选择曦寒基础应用</a></td></tr><tr><td>想先跑起来看看长什么样</td><td><a href="https://basicapp.xihanfun.com" target="_blank" rel="noreferrer">在线预览</a></td></tr><tr><td>要让 Claude Code、Cursor 这类 AI 编程工具按正确的 API 写代码</td><td><a href="#ai-辅助开发">AI 辅助开发</a></td></tr></tbody></table><h2 id="ai-辅助开发" tabindex="-1">AI 辅助开发 <a class="header-anchor" href="#ai-辅助开发" aria-label="Permalink to “AI 辅助开发”">​</a></h2><p>三个文档站都有「AI 辅助开发」一册：给 AI 编程工具的提示词与使用技能、MCP 服务端接入，以及可以直接放进上下文的 LLMs.txt。框架与组件库还各自随版本发布一个离线 CLI，同时也是 MCP 服务端：</p><table tabindex="0"><thead><tr><th>项目</th><th>工具</th><th>在项目根接入</th><th>文档</th></tr></thead><tbody><tr><td>XiHan.Framework</td><td>.NET 工具 <code>XiHan.Framework.Cli</code>，查包、模块类、配置节与文档</td><td><code>dnx XiHan.Framework.Cli --yes -- setup --client claude</code></td><td><a href="https://framework.docs.xihanfun.com/ai/agents" target="_blank" rel="noreferrer">开发框架 · For Agents</a></td></tr><tr><td>XiHan.UI</td><td>npm 包 <code>@xihan-ui/cli</code>，查组件 API、示例、设计令牌与 design.md</td><td><code>npx -y @xihan-ui/cli setup --client claude</code></td><td><a href="https://ui.docs.xihanfun.com/ai/agents" target="_blank" rel="noreferrer">视图组件 · For Agents</a></td></tr><tr><td>XiHan.BasicApp</td><td>不单独发包，后端与前端分别接入上面两个服务端</td><td>在仓库根依次运行上面两条命令</td><td><a href="https://basicapp.docs.xihanfun.com/ai/mcp" target="_blank" rel="noreferrer">基础应用 · MCP Server</a></td></tr></tbody></table><p>两个 CLI 的数据随包离线发布，与各自产品同号。<code>setup</code> 读出项目引用的版本，把钉住版本的 MCP 配置与使用技能写进项目，AI 工具查到的就是项目在用的那一版；<code>--client</code> 还可以换成 <code>cursor</code>、<code>vscode</code> 或 <code>codex</code>。</p><h2 id="版本与发布" tabindex="-1">版本与发布 <a class="header-anchor" href="#版本与发布" aria-label="Permalink to “版本与发布”">​</a></h2><p>各仓库<strong>独立发版</strong>，版本号互不对齐：</p><ul><li>Framework 发布到 <a href="https://www.nuget.org/profiles/XiHanFun" target="_blank" rel="noreferrer">NuGet</a>，版本真源是 <code>framework/props/version.props</code></li><li>BasicApp 随仓库发布，版本真源是 <code>backend/props/version.props</code></li><li>UI 发布到 <a href="https://www.npmjs.com/org/xihan-ui" target="_blank" rel="noreferrer">npm</a>，全部公开包始终同一个版本号，版本真源是 <code>ui/packages/*/*/package.json</code></li><li>四款设计器各自发布到 npm，作用域分别是 <code>@xihan-print</code>、<code>@xihan-flow</code>、<code>@xihan-form</code>、<code>@xihan-report</code>，版本真源是各仓 <code>&lt;产品&gt;/packages/*/package.json</code>（如 <code>print/packages/*/package.json</code>）</li></ul><p>三个产品站导航栏的末项显示该项目当前的版本号；本站「生态」菜单里的徽章显示各项目的发布阶段。</p><h2 id="参与进来" tabindex="-1">参与进来 <a class="header-anchor" href="#参与进来" aria-label="Permalink to “参与进来”">​</a></h2><p>三个仓库在 GitHub（主库）、Gitee 与 GitCode（同步备库）上都可访问，Issue 与 PR 三个平台都收。共同的约定见<a href="./contributing">参与贡献指南</a>与<a href="./code-of-conduct">行为公约</a>。</p>`,34)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};